import { gs, GlideRecord } from '@servicenow/glide';
export function reconcileExpenseToBudget(current, previous) {
    var newStatus = current.getValue('status');
    var oldStatus = previous.getValue('status');
    if (newStatus !== 'recorded' || oldStatus === 'recorded')
        return;
    var budgetId = current.getValue('budget');
    var amount = parseFloat(current.getValue('amount')) || 0;
    if (!budgetId || amount <= 0)
        return;
    var budget = new GlideRecord('x_2248447_csr_ma_2_budget');
    if (budget.get(budgetId)) {
        var spent = parseFloat(budget.getValue('spent')) || 0;
        var committed = parseFloat(budget.getValue('committed')) || 0;
        var approved = parseFloat(budget.getValue('approved')) || 0;
        // Move from committed to spent
        var commitReduction = Math.min(amount, committed);
        budget.setValue('spent', spent + amount);
        budget.setValue('committed', committed - commitReduction);
        // available recalculated by budget BR
        budget.setValue('available', approved - (spent + amount) - (committed - commitReduction));
        budget.update();
        // Check budget alert threshold
        var alertPercent = parseInt(gs.getProperty('x_2248447_csr_ma_2.budget_alert_percent')) || 80;
        var utilization = ((spent + amount) / approved) * 100;
        if (utilization >= alertPercent) {
            gs.addInfoMessage('BUDGET ALERT: Category budget utilization is now at ' + Math.round(utilization) + '% (threshold: ' + alertPercent + '%).');
        }
    }
}
export function budgetHardStop(current, previous) {
    var budgetId = current.getValue('budget');
    var amount = parseFloat(current.getValue('amount')) || 0;
    if (!budgetId || amount <= 0)
        return;
    var budget = new GlideRecord('x_2248447_csr_ma_2_budget');
    if (budget.get(budgetId)) {
        var spent = parseFloat(budget.getValue('spent')) || 0;
        var approved = parseFloat(budget.getValue('approved')) || 0;
        if ((spent + amount) > approved) {
            gs.addErrorMessage('BUDGET HARD STOP: Recording this expense of ' + amount + ' would exceed the approved budget of ' + approved + ' (current spent: ' + spent + '). Please raise a budget exception.');
            current.setAbortAction(true);
        }
    }
}
